/* assistente-afinar.js · IPR Atlas · Terracrua Design
 * Nuno, 07/11/2026, 09h18: «corrige tudo». Caso de origem (ronda de 07/11, 09h): de 02 a 06/11, 469 pessoas abriram o
 * assistente de compra e só 1 chegou ao pedido; não se sabia em que passo desistiam.
 * Corre por cima do assistente.js sem o alterar (se o assistente mudar, isto não estraga nada: só não encontra o que procura).
 *  1. Medição: a cada ecrã do assistente envia ao Google Analytics «assistente_passo» (n.º do passo, fase, título do
 *     ecrã, produto). Se aparecer o erro «Não foi possível registar o pedido», envia «assistente_erro» com a mensagem.
 *  2. O contador deixa de mostrar o total («Passo 3 de 7» passa a «Passo 3»): o total mudava a meio (de 4 para 7).
 *  3. Textos da conta: a conta já se activa com um clique (m90927); deixa de se prometer «escolher a palavra-passe».
 *  4. Janela «O mapa não abriu» (#tcd-pb): em inglês quando o Atlas está em inglês, e com um botão novo para comprar a
 *     Planta ou a Leitura sem mapa (o assistente funciona sem WebGL).
 * Desligar: tirar «assistente-afinar.js» do atlas.json. */
(function () {
  'use strict';
  if (window.__iprAfinar) return;
  window.__iprAfinar = 1;

  function en() { return String(window.IPR_LINGUA || document.documentElement.lang || 'pt').slice(0, 2) === 'en'; }
  function ga(n, p) { try { if (window.gtag) window.gtag('event', n, p || {}); } catch (e) {} }

  // Trocas de texto (pedaços de texto, não frases inteiras, para aguentar pequenas mudanças).
  var TROCAS = [
    ['Recebe um e-mail para escolher a palavra-passe.', 'Recebe um e-mail para entrar com um clique.'],
    ['You get an e-mail to choose a password.', 'You get an e-mail to sign in with one click.'],
    ['vai receber um e-mail para definir a palavra-passe.', 'vai receber um e-mail para entrar com um clique.'],
    ['you will get an e-mail to set your password.', 'you will get an e-mail to sign in with one click.'],
    ['recebe uma ligação para escolher a palavra-passe.', 'recebe uma ligação para entrar com um clique.'],
    ['you get a link to choose a password.', 'you get a link to sign in with one click.']
  ];
  function trocar(raiz, lista) {
    if (!raiz) return;
    var w = document.createTreeWalker(raiz, NodeFilter.SHOW_TEXT, null), n;
    while ((n = w.nextNode())) {
      var v = n.nodeValue, novo = v;
      for (var i = 0; i < lista.length; i++) { if (novo.indexOf(lista[i][0]) >= 0) novo = novo.split(lista[i][0]).join(lista[i][1]); }
      if (novo !== v) n.nodeValue = novo;
    }
  }

  // 6 · sem WebGL, a opção «Toco no terreno no mapa» aparecia como recomendada e não levava a lado nenhum: tira-lhe o selo,
  // põe-na no fim da lista e diz porquê.
  var semMapa = null;
  function mapaAbre() {
    if (semMapa === null) {
      try { var c = document.createElement('canvas'); semMapa = !(c.getContext('webgl2') || c.getContext('webgl')); } catch (e) { semMapa = true; }
    }
    return !semMapa;
  }
  function afinarSemMapa(p) {
    if (mapaAbre()) return;
    var ops = p.querySelectorAll('.ops .op');
    for (var i = 0; i < ops.length; i++) {
      var op = ops[i];
      if (op.getAttribute('data-ipr-sm') || !/on the map|no mapa/i.test(op.textContent || '')) continue;
      op.setAttribute('data-ipr-sm', '1');
      var els = op.querySelectorAll('*');
      for (var j = 0; j < els.length; j++) {
        if (!els[j].children.length && /^(recomendado|recommended)$/i.test((els[j].textContent || '').trim())) els[j].style.display = 'none';
      }
      var tx = op.querySelector('.tx') || op;
      var nota = document.createElement('small');
      nota.textContent = en() ? 'The map did not open in this browser: please choose another option.' : 'O mapa não abriu neste navegador: escolha outra opção.';
      nota.style.cssText = 'display:block;color:#f0b37a';
      tx.appendChild(nota);
      op.style.opacity = '.55';
      if (op.parentNode) op.parentNode.appendChild(op);
    }
  }

  // 7 · a caixa da entrega imediata vem desmarcada (tem de ser o cliente a pedi-la); sem ela, a Planta e a Leitura só ficam
  // disponíveis ao fim de 14 dias. Explica isso junto da caixa, em linguagem simples.
  function afinarEntrega(p) {
    if (p.querySelector('#ipr-entrega-dica')) return;
    var cbs = p.querySelectorAll('input[type=checkbox]');
    for (var i = 0; i < cbs.length; i++) {
      var lb = cbs[i].closest('label') || cbs[i].parentNode;
      if (!lb || !/entrega imediata|immediate delivery/i.test(lb.textContent || '')) continue;
      var d = document.createElement('p');
      d.id = 'ipr-entrega-dica';
      d.textContent = en()
        ? 'Need it now (for the town hall, the bank or the notary)? Tick this box and the document is ready right after payment.'
        : 'Precisa do documento já (para a câmara, o banco ou o notário)? Marque esta caixa e fica pronto logo a seguir ao pagamento.';
      d.style.cssText = 'margin:6px 0 10px;font-size:13px;line-height:1.4;color:#c9d48f;font-weight:600';
      if (lb.nextSibling) lb.parentNode.insertBefore(d, lb.nextSibling); else lb.parentNode.appendChild(d);
      return;
    }
  }

  // 1 a 3 · assistente
  var ultimo = '', ultimoErro = '';
  function afinarPainel() {
    var p = document.getElementById('ipr-as-pn');
    if (!p) return;
    var np = p.querySelector('small.np');
    if (np && /\s(de|of)\s+\d+\s*$/.test(np.textContent)) np.textContent = np.textContent.replace(/\s(de|of)\s+\d+\s*$/, '');
    trocar(p, TROCAS);
    var fase = p.querySelector('ol.pp li.agora'), tit = p.querySelector('.corpo h2'), prod = p.querySelector('.lin b');
    var dados = {
      passo: np ? np.textContent.replace(/\D+/g, '') : '',
      fase: fase ? fase.textContent.trim().slice(0, 40) : '',
      ecra: tit ? tit.textContent.trim().slice(0, 90) : '',
      produto: prod ? prod.textContent.trim().slice(0, 40) : ''
    };
    var chave = dados.passo + '|' + dados.fase + '|' + dados.ecra + '|' + dados.produto;
    if (chave !== ultimo) { ultimo = chave; ga('assistente_passo', dados); }
    afinarSemMapa(p);
    afinarEntrega(p);
    var txt = p.textContent || '';
    var m = /(Não foi possível registar o pedido[^\n]{0,140}|Could not register the order[^\n]{0,140})/.exec(txt);
    if (m && m[1] !== ultimoErro) { ultimoErro = m[1]; ga('assistente_erro', { mensagem: m[1].slice(0, 150), produto: dados.produto }); }
  }

  // 5 · «Encomendar e pagar» que parece não fazer nada (achado no ensaio de 07/11): sem a caixa da Política de Privacidade,
  // o aviso «Falta: …» aparece no fundo do formulário, fora de vista, e o botão parece morto. Ao carregar no botão do rodapé,
  // se houver um aviso «Falta», leva o formulário até ele, realça-o e repete-o por cima do botão.
  document.addEventListener('click', function (e) {
    var b = e.target && e.target.closest ? e.target.closest('#ipr-as-pn .rod button') : null;
    if (!b) return;
    setTimeout(function () {
      var p = document.getElementById('ipr-as-pn');
      if (!p) return;
      var f = p.querySelector('.corpo .falta');
      var velho = document.getElementById('ipr-as-falta');
      var texto = f ? (f.textContent || '').trim() : '';
      if (!texto) { if (velho) velho.remove(); return; }
      try { f.scrollIntoView({ block: 'center', behavior: 'smooth' }); } catch (x) { try { f.scrollIntoView(); } catch (y) {} }
      f.style.outline = '2px solid #d9822b'; f.style.outlineOffset = '4px'; f.style.fontWeight = '600';
      var rod = b.parentNode;
      if (!velho) {
        velho = document.createElement('p');
        velho.id = 'ipr-as-falta';
        velho.setAttribute('role', 'alert');
        velho.style.cssText = 'margin:0 0 8px;width:100%;font-size:13px;line-height:1.4;color:#f0b37a;font-weight:600';
      }
      velho.textContent = texto;
      if (velho.parentNode !== rod) { rod.style.flexWrap = 'wrap'; rod.insertBefore(velho, rod.firstChild); }
      ga('assistente_falta', { texto: texto.slice(0, 120) });
    }, 250);
  }, true);

  // 4 · janela sem mapa
  var PB_EN = [
    ['O mapa não abriu neste navegador', 'The map did not open in this browser'],
    ['O IPR Atlas precisa de aceleração gráfica (WebGL), que parece estar desligada ou indisponível neste navegador ou dispositivo. Não perde nada: pode continuar o pedido sem o mapa.', 'The IPR Atlas needs graphics acceleration (WebGL), which seems to be off or unavailable in this browser or device. You lose nothing: you can carry on with your order without the map.'],
    ['Alguns componentes do mapa não carregaram. Acontece quando a rede (de uma empresa ou instituição, por exemplo) bloqueia o serviço que os fornece. Não perde nada: pode continuar o pedido sem o mapa.', 'Some parts of the map did not load. This happens when a network (of a company or institution, for example) blocks the service that provides them. You lose nothing: you can carry on with your order without the map.'],
    ['Indique o terreno de outra forma', 'Tell us where the land is in another way'],
    ['pela morada, pelo nome da propriedade ou pelos artigos matriciais;', 'by the address, the estate name or the land registry articles;'],
    ['pelas coordenadas de um ponto do terreno (por exemplo 37.4886, -8.1445);', 'by the coordinates of a point on the land (for example 37.4886, -8.1445);'],
    ['por um ficheiro com o limite', 'with a file of the boundary'],
    ['que pode enviar para', 'which you can send to'],
    ['Preparamos o pedido por si e enviamos-lhe o valor antes de qualquer pagamento.', 'We prepare the order for you and send you the price before any payment.'],
    ['Pedir visita técnica sem mapa', 'Ask for a site visit without the map'],
    ['Pedir a Base Cartográfica sem mapa', 'Ask for the Base map without the map'],
    ['Também pode tentar noutro navegador actualizado (Chrome, Firefox, Edge ou Safari), confirmar que a aceleração por hardware está ligada nas definições do navegador, ou abrir o IPR Atlas noutro computador ou telemóvel.', 'You can also try another up-to-date browser (Chrome, Firefox, Edge or Safari), check that hardware acceleration is on in the browser settings, or open the IPR Atlas on another computer or phone.'],
    ['Tentar outra vez', 'Try again'],
    ['Fechar e ver a página sem o mapa', 'Close and see the page without the map']
  ];
  function afinarPlanoB() {
    var pb = document.getElementById('tcd-pb');
    if (!pb || pb.hidden || pb.style.display === 'none') return;
    if (en()) trocar(pb, PB_EN);
    if (!document.getElementById('ipr-pb-comprar') && typeof window.iprAssistenteComprar === 'function') {
      var ref = pb.querySelector('a[href*="visita"], a[href*="base"]') || document.getElementById('tcd-pb-r');
      var host = ref ? ref.parentNode : null;
      if (!host) return;
      // O iprAssistenteComprar só aceita «planta», «leitura» ou «base»: um botão por produto.
      var cx = document.createElement('div');
      cx.id = 'ipr-pb-comprar';
      [['planta', en() ? 'Buy the Location plan without the map' : 'Comprar a Planta de Localização sem mapa'],
       ['leitura', en() ? 'Buy the Land report without the map' : 'Comprar a Leitura Territorial sem mapa']].forEach(function (o) {
        var a = document.createElement('a');
        a.href = '#';
        a.textContent = o[1];
        if (ref) a.style.cssText = ref.style.cssText;
        a.style.display = 'block';
        a.style.marginBottom = '10px';
        a.addEventListener('click', function (e) {
          e.preventDefault();
          pb.hidden = true; pb.style.display = 'none';
          ga('atlas_plano_b_comprar', { produto: o[0] });
          try { window.iprAssistenteComprar(o[0]); } catch (x) {}
        });
        cx.appendChild(a);
      });
      host.insertBefore(cx, host.firstChild);
    }
  }

  var agendado = 0;
  function correr() { agendado = 0; try { afinarPainel(); } catch (e) {} try { afinarPlanoB(); } catch (e) {} }
  // v4 (10h05): setTimeout em vez de requestAnimationFrame (este pode ficar parado e deixava o agendado preso), e uma
  // passagem de reserva a cada 1,5 s enquanto o assistente ou a janela sem mapa estiverem abertos.
  function agendar() { if (!agendado) { agendado = 1; setTimeout(correr, 40); } }
  setInterval(function () { if (document.getElementById('ipr-as-pn') || document.getElementById('tcd-pb')) correr(); }, 1500);
  if (window.MutationObserver) {
    // Só listas de filhos no documento (o assistente redesenha-se por innerHTML); atributos só na janela sem mapa,
    // para não correr a cada movimento do mapa.
    new MutationObserver(agendar).observe(document.documentElement, { childList: true, subtree: true });
    var vigiaPb = function () {
      var pb = document.getElementById('tcd-pb');
      if (pb) new MutationObserver(agendar).observe(pb, { attributes: true, attributeFilter: ['style', 'hidden'] });
      else setTimeout(vigiaPb, 1000);
    };
    vigiaPb();
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', correr); else correr();
})();

