        (a.eur || EUR[a.k] ? "<input class='e' type='number' min='0' step='50' data-eur='" + a.k + "' value='" + (EUR[a.k] || 0) + "' aria-label='€/ha'>" : "–") +
        "</td><td class='n' data-sub='" + a.k + "'>" + fmt(v * (EUR[a.k] || 0)) + "</td></tr>";
